import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第七十八章 痛苦如同树的生长","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/78第七十八章 痛苦如同树的生长.md","filePath":"meditation/巴利文大藏经/78第七十八章 痛苦如同树的生长.md"}'),o={name:"meditation/巴利文大藏经/78第七十八章 痛苦如同树的生长.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第七十八章-痛苦如同树的生长",tabindex:"-1"},[l("第七十八章 痛苦如同树的生长 "),e("a",{class:"header-anchor",href:"#第七十八章-痛苦如同树的生长","aria-label":'Permalink to "第七十八章 痛苦如同树的生长"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部12相应55经/大树经(因缘相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，当执着和挂念世间的事物，沉迷于获得、拥有、享受这些事物带来的快乐、喜悦、满足的感受之中的时候，就会让贪爱增长，以「贪爱」为前提条件就会产生出「取」，以「取」为前提条件就会产生出「有」，以「有」为前提条件就会产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼聚集、出现的过程，世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。",-1),e("p",null,"弟子们，就如同一颗大树，它的根向地下生长，它牢牢的根植于大地，并从大地中吸取水份、养料。这样这颗大树就能长时间的生长、存在。同样的道理，弟子们，当执着和挂念世间的事物，沉迷于获得、拥有、享受这些事物带来的快乐、满足、喜悦的感受之中的时候，就如同大树根植于大地，从大地中吸取水份和养料一样，那么贪爱就会持续的增长，以「贪爱」为前提条件就会产生出「取」，以「取」为前提条件就会产生出「有」，以「有」为前提条件就会产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼聚集、出现的过程，世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。",-1),e("p",null,"弟子们，当不执着和挂念世间的一切事物，不沉迷于获得、拥有、享受这些事物带来的快乐、喜悦、满足的感受之中的时候，明白世间一切的事物给自己带来的，最终都是痛苦的感受，那么贪爱就会逐渐的褪去、灭尽、消失。当「贪爱」灭尽了，「取」就灭除了。「取」灭尽了，「有」就灭除了。「有」灭尽了，「生」就灭除了。「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼灭除、灭尽的过程。世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的逆行就能从生死轮回的烦恼和痛苦中解脱出来。",-1),e("p",null,"弟子们，就如同有个男子带上挖土的铲子和装土的竹篓，来到一棵大树的旁边，他奋力的挖土，将这颗大树的所有根部，包括细小的根须都挖断了，他将这颗大树连根挖出，然后他用斧头、锯子将大树分割成无数的小木块，又将这些小木块压成粉末，放在太阳下面曝晒，除去木粉末中的水份，之后这个男子将干燥的木粉末投入大火中焚烧，木粉末燃烧成灰后，这些灰烬或者被大风吹走，或者被投入湍急流淌的大江、大河之中被冲走。弟子们，像这样，这颗大树被连根挖出，被斧头、锯子分割成无数的小木块，又被压成木粉末，被曝晒除去水份，被焚烧成灰烬，最后这些灰烬被大风吹走，被投入大江、大河中被冲走，这样这颗大树就不存在了，就消失了，以后也不可能再生根发芽，未来这棵大树已经不可能再出现，它已经完全灭尽、消失了。同样的道理，弟子们，当不再挂念和执着世间的一切事物，不再沉迷于获得、拥有、享受这些事物带来的快乐、喜悦、满足的感受之中的时候，明白世间一切的事物给自己带来的，最终都是痛苦的感受，那么就如同大树被连根挖出，被斧头、锯子分割成无数的小木块，被压成木粉末，被曝晒除去水份，被大火焚烧成灰烬，被大风吹走，被投入大江、大河中被冲走一样，贪爱也会逐渐褪去、灭尽、消失。「贪爱」灭尽了，「取」就灭除了。「取」灭尽了，「有」就灭除了。「有」灭尽了，「生」就灭除了。「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼灭除、灭尽的过程。世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的逆行就能从生死轮回的烦恼和痛苦中解脱出来。",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
